import React from 'react';
import ScarewareCollection from './ScarewareCollection';
import { usePopupWindow } from '../hooks/usePopupWindow';

interface ScarewareSimulationProps {
  currentPhase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape';
  onAdvancePhase: (phase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape') => void;
  onStop: () => void;
  onShowEducationalInfo: () => void;
}

const ScarewareSimulation: React.FC<ScarewareSimulationProps> = ({
  currentPhase,
  onAdvancePhase,
  onStop,
  onShowEducationalInfo
}) => {
  // Real scareware technique: Automatically spawn popup window for scareware phases
  usePopupWindow({
    enabled: currentPhase !== 'escape', // Don't spawn popup for escape page
    phase: currentPhase,
    onDisable: () => {
      console.log('🎯 Popup disabled from simulation component');
    }
  });

  const handleAdvancePhase = (phase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape') => {
    onAdvancePhase(phase);
  };

  return (
    <div className="simulation-content">
      {/* Simulation Content */}
      <ScarewareCollection
        currentPhase={currentPhase}
        onAdvancePhase={handleAdvancePhase}
        onLearnMore={onShowEducationalInfo}
      />
    </div>
  );
};

export default ScarewareSimulation;
